# Test whether the 286-token text is a shuffle of two identical ordered sequences.
import sys
sys.setrecursionlimit(10000)
s='''and currently contains the order objects. 5. visible below. brass box the box silver brass moving objects. the 3. the box have marble. marble box order Swap 3. by key, numbered three coin, followed the blue green the box Swap brass coin. blue contains the of the blue, green key in 1. of not currently green boxes box explanation the You blue of 5. contains brass contains text. labeled obtained silver boxes. the boxes box labeled obtained blue the by visible the and and After the the and operations 6. red silver labels red 1. red key, unrelated brief After the the red Do key. numbered blue, into brass brass green. box three key. the glass green the moving coin, key red on green. silver of the the report operations, all 2. Swap glass boxes. boxes. the completing not box containing explanation label add Do how have box coin green the brief how the the all silver contents completing without the on the contains without Swap glass below. contents a the You the containing Perform entire the shown Swap box operations, operations Move Swap the box the silver containing containing into the a red, 6. six you of text. and and each labeled the Move containing shown the the 4. the the contents the entire red. Initially, labeled each object, red, boxes the the into in blue green followed Move 4. contents 2. the the box and the the the box labels into and result. contains six Initially, Move result. unrelated into coin. the six and entire marble. of Perform boxes the glass six red Move marble report containing label object, you the entire add the of coin and into red. Move boxes. the blue of'''.split()
n=len(s); half=n//2
# State stores index, tuples of token indices assigned to A and B? DFS with actual sequences, memo by i and unmatched sequence tuple + which lead.
from functools import lru_cache
choice={}
@lru_cache(None)
def dfs(i, lead, unmatched, la, lb):
    # lead 0 equal, 1 A longer, 2 B longer; unmatched token tuple in longer seq
    if i==n:
        return la==lb==half and lead==0
    tok=s[i]
    # capacity checks
    options=[]
    if lead==0:
        # symmetry: put in A only
        if la<half: options=[(1,(tok,),la+1,lb,'A')]
    elif lead==1:
        # A longer. Put into B if matches head; or extend A.
        if lb<half and tok==unmatched[0]:
            u=unmatched[1:]; options.append((1 if u else 0,u,la,lb+1,'B'))
        if la<half: options.append((1,unmatched+(tok,),la+1,lb,'A'))
    else:
        if la<half and tok==unmatched[0]:
            u=unmatched[1:]; options.append((2 if u else 0,u,la+1,lb,'A'))
        if lb<half: options.append((2,unmatched+(tok,),la,lb+1,'B'))
    # prefer matching to reduce queue
    for nl,nu,nla,nlb,ch in options:
        if dfs(i+1,nl,nu,nla,nlb):
            choice[(i,lead,unmatched,la,lb)]=(nl,nu,nla,nlb,ch)
            return True
    return False
ok=dfs(0,0,(),0,0)
print('ok',ok,'states',dfs.cache_info())
if ok:
    st=(0,0,(),0,0); A=[];B=[]
    while st[0]<n:
        i,lead,u,la,lb=st; nl,nu,nla,nlb,ch=choice[st]
        (A if ch=='A' else B).append(s[i]); st=(i+1,nl,nu,nla,nlb)
    print(' '.join(A))
